
const SPAN_KIND_INTERNAL = 1;
const SPAN_KIND_CLIENT = 3;

export const TRACED_CHANNELS = {
	"h3.request"(channel, data) {
		const { event, type } = data;
		const method = event.req.method;
		const path = event.url.pathname;
		
		
		
		const route = event.context?.matchedRoute?.route;
		const target = route || path;
		const attributes = [
			{
				key: "http.request.method",
				value: { stringValue: method }
			},
			{
				key: "url.path",
				value: { stringValue: path }
			},
			{
				key: "h3.handler_type",
				value: { stringValue: type }
			}
		];
		if (route) {
			attributes.push({
				key: "http.route",
				value: { stringValue: route }
			});
		}
		return {
			name: type === "middleware" ? `middleware ${method} ${target}` : `${method} ${target}`,
			kind: SPAN_KIND_INTERNAL,
			attributes
		};
	},
	"srvx.request"(channel, data) {
		const { request, result } = data;
		const method = request.method;
		const path = new URL(request.url).pathname;
		
		
		
		
		
		const route = request.context?.matchedRoute?.route;
		const attributes = [{
			key: "http.request.method",
			value: { stringValue: method }
		}, {
			key: "url.path",
			value: { stringValue: path }
		}];
		if (route) {
			attributes.push({
				key: "http.route",
				value: { stringValue: route }
			});
		}
		if (result) {
			attributes.push({
				key: "http.response.status_code",
				value: { intValue: result.status }
			});
		}
		return {
			name: `${method} ${route || path}`,
			kind: SPAN_KIND_INTERNAL,
			attributes
		};
	},
	"srvx.middleware"(channel, data) {
		const { request, middleware } = data;
		const handlerName = middleware.handler.name;
		const attributes = [{
			key: "srvx.middleware.index",
			value: { intValue: middleware.index }
		}, {
			key: "http.request.method",
			value: { stringValue: request.method }
		}];
		if (handlerName) {
			attributes.push({
				key: "srvx.middleware.name",
				value: { stringValue: handlerName }
			});
		}
		return {
			name: `middleware ${handlerName || `#${middleware.index}`}`,
			kind: SPAN_KIND_INTERNAL,
			attributes
		};
	},
	...Object.fromEntries([
		"getItem",
		"getItems",
		"getItemRaw",
		"getMeta",
		"getKeys",
		"hasItem",
		"setItem",
		"setItems",
		"setItemRaw",
		"removeItem",
		"clear"
	].map((operation) => [`unstorage.${operation}`, (channel, data) => {
		const { driver, base, keys } = data;
		const operation = channel.slice("unstorage.".length);
		
		const attributes = [{
			key: "db.operation",
			value: { stringValue: operation }
		}];
		if (driver?.name) attributes.push({
			key: "db.system",
			value: { stringValue: driver.name }
		});
		if (base) attributes.push({
			key: "unstorage.base",
			value: { stringValue: base }
		});
		if (keys) attributes.push({
			key: "unstorage.keys_count",
			value: { intValue: keys.length }
		});
		return {
			name: base ? `${operation} ${base}` : operation,
			kind: SPAN_KIND_CLIENT,
			attributes
		};
	}]))
};
